import React, { useState } from 'react';
import { 
  Home, List, BookOpen, Database, ChevronLeft, 
  Triangle, ArrowUp, ArrowDown, ChevronRight 
} from 'lucide-react';
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid, 
  ResponsiveContainer, LineChart, Line
} from 'recharts';

// --- 型定義 ---
interface VolumeInfo {
  number: number;
  isbn: string;
  releaseDate: string;
}

// --- モックデータ ---
const trendData = [
  { name: '第6号', onePiece: 1.2, jjk: 2.1, mha: 2.8 },
  { name: '第7号', onePiece: 1.8, jjk: 1.5, mha: 3.0 },
  { name: '第8号', onePiece: 1.1, jjk: 2.3, mha: 1.5 },
  { name: '第9号', onePiece: 1.5, jjk: 2.0, mha: 2.2 },
  { name: '第10号', onePiece: 1.0, jjk: 1.8, mha: 2.5 },
];

// --- サブコンポーネント ---

// 1. サイドバーのアイテム
const SidebarItem = ({ icon, label, active = false }: { icon: React.ReactNode, label: string, active?: boolean }) => (
  <div style={{
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    padding: '12px 20px',
    backgroundColor: active ? 'rgba(255, 255, 255, 0.05)' : 'transparent',
    borderLeft: active ? '4px solid #3b82f6' : '4px solid transparent',
    cursor: 'pointer',
    color: active ? '#60a5fa' : '#94a3b8',
    transition: 'all 0.2s'
  }}>
    {icon}
    <span style={{ fontSize: '14px', fontWeight: active ? 'bold' : 'normal' }}>{label}</span>
  </div>
);

// 2. 右側詳細のステータスカード
const StatCard = ({ title, value, unit, color, icon, border }: any) => (
  <div style={{
    backgroundColor: color,
    border: border || 'none',
    borderRadius: '4px',
    padding: '8px',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
    alignItems: 'center',
    aspectRatio: '1/1'
  }}>
    <div style={{ fontSize: '9px', opacity: 0.7, whiteSpace: 'nowrap' }}>{title}</div>
    <div style={{ display: 'flex', alignItems: 'baseline', gap: '2px' }}>
      <span style={{ fontSize: '22px', fontWeight: 'bold', fontStyle: 'italic' }}>{value}</span>
      <span style={{ fontSize: '10px' }}>{unit}</span>
      {icon}
    </div>
  </div>
);

// --- メインコンポーネント ---

export default function LineChartFromCSV() {
  const volume: VolumeInfo = {
    number: 108,
    isbn: "978-4-08-884013-0",
    releaseDate: "2024年3月4日"
  };

  return (
    <div style={{ 
      display: 'flex', 
      backgroundColor: '#0f172a', 
      minHeight: '100vh', 
      color: 'white', 
      fontFamily: '"Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif' 
    }}>

      {/* 左：サイドバー */}
      <aside style={{ width: '220px', backgroundColor: '#1a2235', borderRight: '1px solid #2d3748', paddingTop: '20px' }}>
        <h1 style={{ padding: '0 20px', fontSize: '18px', fontWeight: 'bold', marginBottom: '30px', letterSpacing: '0.05em' }}>
          ジャンプ順位管理
        </h1>
        <nav>
          <SidebarItem icon={<Home size={18}/>} label="ホーム" active />
          <SidebarItem icon={<List size={18}/>} label="号別ランキング" />
          <SidebarItem icon={<BookOpen size={18}/>} label="作品一覧" />
          <SidebarItem icon={<Database size={18}/>} label="データ管理" />
        </nav>
      </aside>

      {/* 中央：ランキングサマリー */}
      <section style={{ flex: 1, backgroundColor: '#161d2f', padding: '30px', borderRight: '1px solid #2d3748' }}>
        <div style={{ marginBottom: '40px' }}>
          <h2 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '8px' }}>2026年 第10号</h2>
          <div style={{ width: '60px', height: '3px', backgroundColor: '#3b82f6' }}></div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '40px' }}>
          {['ONE PIECE', '呪術廻戦', '僕のヒーローアカデミア', 'サカモトデイズ', 'アオのハコ'].map((name, i) => (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
              <div style={{ fontSize: '20px', fontWeight: 'bold', fontStyle: 'italic', width: '40px' }}>
                {i + 1}<span style={{ fontSize: '12px', fontStyle: 'normal', marginLeft: '2px' }}>位</span>
              </div>
              <div style={{ fontSize: '18px', fontWeight: '500' }}>{name}</div>
            </div>
          ))}
        </div>

        <button style={{
          width: '100%', padding: '12px', backgroundColor: '#252f48', border: '1px solid #334155',
          borderRadius: '6px', color: 'white', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '8px'
        }}>
          全順位を見る <ChevronRight size={16} />
        </button>

        <div style={{ marginTop: '50px' }}>
          <h3 style={{ fontSize: '14px', color: '#94a3b8', borderBottom: '1px solid #2d3748', paddingBottom: '8px', marginBottom: '20px' }}>トレンド推移</h3>
          <div style={{ height: '180px' }}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={trendData}>
                <CartesianGrid vertical={false} stroke="#2d3748" strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{fill: '#64748b', fontSize: 11}} axisLine={false} tickLine={false} />
                <YAxis reversed domain={[1, 4]} hide />
                <Line type="monotone" dataKey="onePiece" stroke="#60a5fa" strokeWidth={3} dot={{r: 4, fill: '#fff'}} />
                <Line type="monotone" dataKey="jjk" stroke="#f87171" strokeWidth={2} dot={{r: 3}} />
                <Line type="monotone" dataKey="mha" stroke="#4ade80" strokeWidth={2} dot={{r: 3}} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </section>

      {/* 右：個別作品分析 */}
      <section style={{ width: '380px', backgroundColor: '#161d2f', padding: '30px' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '30px' }}>
          <ChevronLeft size={24} style={{ cursor: 'pointer', color: '#94a3b8' }} />
          <h2 style={{ fontSize: '20px', fontWeight: 'bold', letterSpacing: '0.1em' }}>ONE PIECE</h2>
          <div style={{ width: '24px' }} />
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '10px', marginBottom: '40px' }}>
          <StatCard title="最新順位" value="1" unit="位" color="#2a5496" />
          <StatCard title="平均順位" value="2.4" unit="位" color="#1e4d40" icon={<Triangle size={8} fill="#4ade80" color="#4ade80" style={{marginLeft: '2px'}} />} />
          <StatCard title="最高順位" value="1" unit="位" color="#1e293b" border="1px solid #334155" icon={<ArrowUp size={12} color="#ef4444" style={{marginLeft: '2px'}} />} />
          <StatCard title="最低順位" value="6" unit="位" color="#1e293b" border="1px solid #334155" icon={<ArrowDown size={12} color="#ef4444" style={{marginLeft: '2px'}} />} />
        </div>

        <h3 style={{ fontSize: '14px', color: '#94a3b8', borderBottom: '1px solid #2d3748', paddingBottom: '8px', marginBottom: '20px' }}>順位推移</h3>
        <div style={{ height: '200px', marginBottom: '40px' }}>
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendData}>
              <defs>
                <linearGradient id="colorBlue" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                  <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid vertical={false} stroke="#2d3748" />
              <XAxis dataKey="name" hide />
              <YAxis reversed domain={[0.5, 3.5]} hide />
              <Area type="monotone" dataKey="onePiece" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorBlue)" dot={{ r: 5, fill: '#fff', stroke: '#3b82f6', strokeWidth: 2 }} />
            </AreaChart>
          </ResponsiveContainer>
        </div>

        {/* 単行本リンクエリア */}
        <div style={{ 
          backgroundColor: '#1e293b', padding: '15px', borderRadius: '8px', border: '1px solid #334155', display: 'flex', gap: '15px' 
        }}>
          <div style={{ 
            width: '70px', height: '100px', backgroundColor: '#0f172a', borderRadius: '4px', 
            display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '10px', color: '#475569' 
          }}>COVER</div>
          <div style={{ flex: 1 }}>
            <h4 style={{ margin: '0 0 5px 0', fontSize: '15px' }}>ONE PIECE {volume.number}巻</h4>
            <p style={{ margin: 0, fontSize: '11px', color: '#94a3b8' }}>発売日: {volume.releaseDate}</p>
            <a 
              href={`https://www.shueisha.co.jp/books/items/contents.html?isbn=${volume.isbn}`}
              target="_blank" rel="noopener noreferrer"
              style={{ 
                marginTop: '12px', display: 'inline-block', backgroundColor: '#2563eb', color: 'white', 
                padding: '8px 16px', borderRadius: '4px', fontSize: '12px', textDecoration: 'none', fontWeight: 'bold'
              }}
            >
              詳細を見る
            </a>
          </div>
        </div>
      </section>
    </div>
  );
}
